#include <stdio.h>
#include <stdint.h>
#include <limits.h>

/* 饱和加法：媒体处理 / 量化推理里需要的是饱和，而不是回绕 */
static int sat_add(int a, int b) {
    int r;
    if (__builtin_add_overflow(a, b, &r)) {
        return (a > 0) ? INT_MAX : INT_MIN;
    }
    return r;
}

int main(void) {
    printf("=== unsigned wraps mod 2^n (defined) ===\n");
    uint8_t a = 200, b = 100;
    printf("  uint8_t 200 + 100 = %u     (300 mod 256, guaranteed by the standard)\n",
           (unsigned)(uint8_t)(a + b));
    uint32_t m = 4000000000u;
    printf("  uint32 4000000000 + 400000000 = %u   (mod 2^32, guaranteed)\n",
           m + 400000000u);

    printf("\n=== signed overflow is UNDEFINED BEHAVIOUR ===\n");
    printf("  int 2000000000 + 2000000000 has no defined result; the compiler may assume it never happens\n");

    printf("\n=== detecting it WITHOUT triggering UB ===\n");
    int x = 2000000000, y = 2000000000, r = 0;
    if (__builtin_add_overflow(x, y, &r)) {
        printf("  __builtin_add_overflow(%d, %d) -> OVERFLOW DETECTED\n", x, y);
    } else {
        printf("  sum = %d\n", r);
    }
    if (__builtin_mul_overflow(x, 2, &r)) {
        printf("  __builtin_mul_overflow(%d, 2) -> OVERFLOW DETECTED\n", x);
    }

    printf("\n=== INT_MIN edge cases ===\n");
    printf("  INT_MAX = %d, INT_MIN = %d\n", INT_MAX, INT_MIN);
    printf("  (int)((unsigned)INT_MAX + 1u) = %d   (implementation-defined wrap)\n",
           (int)((unsigned)INT_MAX + 1u));
    printf("  INT_MIN / -1 is UB on int; as long long it is %lld\n", (long long)INT_MIN / -1LL);

    printf("\n=== saturating add ===\n");
    printf("  sat_add(2000000000, 2000000000)   = %d\n", sat_add(2000000000, 2000000000));
    printf("  sat_add(-2000000000, -2000000000) = %d\n", sat_add(-2000000000, -2000000000));
    printf("  sat_add(1, 2)                     = %d\n", sat_add(1, 2));
    return 0;
}
